package com.hau.notification.domain;import com.hau.notification.domain.model.*;import org.junit.jupiter.api.Test;import java.time.Instant;import java.util.UUID;import static org.assertj.core.api.Assertions.*;class NotificationTest{@Test void marksUnreadOnce(){var n=Notification.unread(UUID.randomUUID(),NotificationType.QUESTION_APPROVED,"Approved","Done",null,null,Instant.EPOCH);var read=n.markRead(Instant.EPOCH.plusSeconds(1));assertThat(read.isRead()).isTrue();assertThat(read.markRead(Instant.EPOCH.plusSeconds(2))).isSameAs(read);}}
